```rust
pub fn get_blob(&self) -> Result<Blob<B>, Error> {
    self.expect_type(FlexBufferType::Blob)?;
    Ok(Blob(
        self.buffer
            .slice(self.address..self.address + self.length())
            .ok_or(Error::IndexOutOfBounds)?,
